"""Executable regression examples, preserving every original Python block."""
BLOCKS = ('import json\n'
 'from pathlib import Path\n'
 '\n'
 'METRICS = {\n'
 '    "train_loss": ("train/loss", "mean_loss"),\n'
 '    "train_acc": ("train/accuracy", "percent"),\n'
 '    "val_loss": ("validation/loss", "mean_loss"),\n'
 '    "val_acc": ("validation/accuracy", "percent"),\n'
 '}\n'
 '\n'
 '\n'
 'def log_history(run, history, *, first_new_epoch=1):\n'
 '    if type(first_new_epoch) is not int or first_new_epoch < 1:\n'
 '        raise ValueError("first_new_epoch must be a positive integer")\n'
 '    batch = []\n'
 '    for index in range(first_new_epoch - 1, len(history["train_loss"])):\n'
 '        for key, (name, unit) in METRICS.items():\n'
 '            value = history[key][index]\n'
 '            if value is not None:\n'
 '                batch.append(dict(name=name, value=value, unit=unit,\n'
 '                                  source="trainer_history", epoch=index + 1))\n'
 '            if len(batch) == 256:\n'
 '                run.log_metrics(batch)\n'
 '                batch = []\n'
 '    if batch:\n'
 '        run.log_metrics(batch)\n'
 '\n'
 '\n'
 'def train_and_record(run, trainer, train, val=None, *, epochs,\n'
 '                     checkpoint_path, resume_from=None, first_new_epoch=1,\n'
 '                     ownership="copy"):\n'
 '    checkpoint_path = Path(checkpoint_path)\n'
 '    if checkpoint_path.exists():\n'
 '        raise ValueError("choose a fresh checkpoint output path")\n'
 '    # All plans/components/loaders belong to the caller. Checkpoint profile\n'
 '    # requires callbacks=() and the original total epoch budget on resume.\n'
 '    run.start()\n'
 '    try:\n'
 '        history = trainer.fit(train, val, epochs=epochs,\n'
 '                              save_last_to=checkpoint_path, resume_from=resume_from)\n'
 '    except BaseException as workload_error:\n'
 '        # Secondary tracking errors cannot replace the original workload error.\n'
 '        # A completed-epoch observation is not proof that its checkpoint saved.\n'
 '        try:\n'
 '            log_history(run, trainer.history, first_new_epoch=first_new_epoch)\n'
 '        except Exception:\n'
 '            pass\n'
 '        if checkpoint_path.is_file():\n'
 '            try:\n'
 '                run.add_artifact(checkpoint_path, kind="checkpoint",\n'
 '                                 ownership=ownership, role="output")\n'
 '            except Exception:\n'
 '                pass\n'
 '        try:\n'
 '            if isinstance(workload_error, KeyboardInterrupt):\n'
 '                run.interrupt("caller_keyboard_interrupt")\n'
 '            else:\n'
 '                run.fail("training_exception", failure_domain="workload",\n'
 '                         workload_outcome="failed")\n'
 '        except Exception:\n'
 '            pass\n'
 '        raise\n'
 '    try:\n'
 '        log_history(run, history, first_new_epoch=first_new_epoch)\n'
 '    except Exception:\n'
 '        try:\n'
 '            run.fail("history_logging", failure_domain="tracking",\n'
 '                     workload_outcome="succeeded")\n'
 '        except Exception:\n'
 '            pass\n'
 '        raise\n'
 '    try:\n'
 '        # Terminal/no-op resume may produce no new checkpoint file.\n'
 '        artifact = (run.add_artifact(checkpoint_path, kind="checkpoint",\n'
 '                    ownership=ownership, role="output")\n'
 '                    if checkpoint_path.is_file() else None)\n'
 '    except Exception:\n'
 '        try:\n'
 '            run.fail("checkpoint_ingest", failure_domain="artifact",\n'
 '                     workload_outcome="succeeded")\n'
 '        except Exception:\n'
 '            pass\n'
 '        raise\n'
 '    try:\n'
 '        no_new_epochs = len(history["train_loss"]) < first_new_epoch\n'
 '        run.finish(reason="resume_no_new_epochs" if no_new_epochs else "completed")\n'
 '    except Exception:\n'
 '        try:\n'
 '            run.fail("tracking_finalize", failure_domain="tracking",\n'
 '                     workload_outcome="succeeded")\n'
 '        except Exception:\n'
 '            pass\n'
 '        raise\n'
 '    return history, artifact\n'
 '\n'
 '\n'
 'def record_benchmark(run, runner, directory):\n'
 '    directory = Path(directory)\n'
 '    directory.mkdir(parents=True, exist_ok=False)\n'
 '    run.start()\n'
 '    # Measurement returns before any export/artifact I/O starts.\n'
 '    result = runner.run()\n'
 '    data = result.to_dict()\n'
 '    association = dict(benchmark_schema_version=data["schema_version"],\n'
 '                       benchmark_run_id=data["identity"]["run_id"],\n'
 '                       experiment_run_id=run.id, assertion_source="caller")\n'
 '    artifacts = []\n'
 '    for filename, kind, export in (\n'
 '            ("result.json", "benchmark_json", result.to_json),\n'
 '            ("summary.csv", "benchmark_summary", result.to_csv),\n'
 '            ("samples.csv", "benchmark_samples", result.to_samples_csv)):\n'
 '        path = directory / filename\n'
 '        export(path)\n'
 '        artifacts.append(run.add_artifact(path, kind=kind, ownership="copy",\n'
 '                                          role="output", metadata=association))\n'
 '    run.finish()\n'
 '    return result, artifacts\n'
 '\n'
 '\n'
 'def record_comparison(run, left, right, path, artifact_ids):\n'
 '    from hyso.benchmark import compare_results\n'
 '    report = compare_results(left, right)\n'
 '    # compare_results returns validated finite plain data. No default=str or pickle.\n'
 '    encoded = json.dumps(report, allow_nan=False, ensure_ascii=False, sort_keys=True)\n'
 '    with Path(path).open("x", encoding="utf-8") as stream:\n'
 '        stream.write(encoded)\n'
 '    run.start()\n'
 '    artifact = run.add_artifact(path, kind="comparison_json", ownership="copy",\n'
 '                               role="report", metadata={"input_artifact_ids": artifact_ids,\n'
 '                               "assertion_source": "caller"})\n'
 '    run.finish()\n'
 '    return report, artifact\n',
 'import tempfile\n'
 'import torch\n'
 'from torch import nn\n'
 'from torch.utils.data import DataLoader, TensorDataset\n'
 'from hyso.experiments import ExperimentManager\n'
 'from hyso.models.modular import ModularCNN\n'
 'from hyso.training import Trainer\n'
 'from hyso.benchmark import BenchmarkRunner\n'
 '\n'
 'work = Path(tempfile.mkdtemp(prefix="hyso-manual-"))\n'
 'root = work / "runs"\n'
 'manager = ExperimentManager(root)\n'
 'manager.close()\n'
 'ExperimentManager.migrate_store(root)\n'
 'manager = ExperimentManager(root)\n'
 'experiment = manager.create_experiment("manual integration")\n'
 'config = dict(input_channels=1, num_classes=2, widths=[3], repeats=[1],\n'
 '              strides=[1], attention="eca", norm="batch")\n'
 'inputs = torch.linspace(-1, 1, 4 * 25).reshape(4, 1, 5, 5)\n'
 'targets = torch.tensor([0, 1, 0, 1])\n'
 'train = DataLoader(TensorDataset(inputs, targets), batch_size=2, num_workers=0)\n'
 'val = DataLoader(TensorDataset(inputs, targets), batch_size=2, num_workers=0)\n'
 'model = ModularCNN(**config)\n'
 'optimizer = torch.optim.SGD(model.parameters(), lr=.01)\n'
 'trainer = Trainer(model, optimizer=optimizer, loss_fn=nn.CrossEntropyLoss(),\n'
 '                  model_config=config, callbacks=())\n'
 'training = manager.create_run(experiment["id"], "training", config)\n'
 'history, checkpoint_artifact = train_and_record(\n'
 '    training, trainer, train, val, epochs=2, checkpoint_path=work / "last.pth")\n'
 '\n'
 '# Reference alternative: add it before terminal finish in your own workflow.\n'
 '# reference = running_run.add_artifact(path, ownership="reference", role="output")\n'
 '# manager.verify_artifact(reference["id"], path=path)\n'
 '# Locator is redacted by default; retain_locator=True opts into path persistence.\n'
 'assert manager.verify_artifact(checkpoint_artifact["id"])["status"] == "verified"\n',
 'from hyso.checkpoint import load_training_checkpoint\n'
 '\n'
 '\n'
 'def retry_from_checkpoint(manager, parent_id, artifact_id, checkpoint_path,\n'
 '                          make_trainer, train, val, *, epochs, output_path):\n'
 '    if manager.verify_artifact(artifact_id, path=checkpoint_path)["status"] != "verified":\n'
 '        raise ValueError("checkpoint identity is unavailable")\n'
 '    inspector = make_trainer()\n'
 '    metadata = load_training_checkpoint(checkpoint_path, inspector.model,\n'
 '        optimizer=inspector.optimizer, scheduler=inspector.scheduler,\n'
 '        scaler=inspector.scaler, ema=inspector.ema, restore_rng=False)\n'
 '    completed = metadata["completed_epochs"]\n'
 '    parent = manager.get_run(parent_id).to_dict()\n'
 '    retry = manager.create_run(parent["experiment_id"], parent["kind"], parent["config"],\n'
 '        provenance={"resume_completed_epochs": completed},\n'
 '        retry_of_run_id=parent_id, resume_artifact_id=artifact_id)\n'
 '    fresh = make_trainer()\n'
 '    history, artifact = train_and_record(retry, fresh, train, val, epochs=epochs,\n'
 '        checkpoint_path=output_path, resume_from=checkpoint_path,\n'
 '        first_new_epoch=completed + 1)\n'
 '    assert all(history[key][:completed] == values\n'
 '               for key, values in metadata["history"].items())\n'
 '    return retry, fresh, history, artifact\n',
 'benchmark = manager.create_run(experiment["id"], "benchmark", {"precision": "fp32"})\n'
 'runner = BenchmarkRunner(model, input_shape=(2, 1, 5, 5), device="cpu",\n'
 '                         warmup_iterations=1, measure_iterations=2, repeats=2)\n'
 'left, left_artifacts = record_benchmark(benchmark, runner, work / "benchmark-a")\n'
 'other = manager.create_run(experiment["id"], "benchmark", {"precision": "fp32"})\n'
 'right, right_artifacts = record_benchmark(other, runner, work / "benchmark-b")\n'
 'comparison = manager.create_run(experiment["id"], "evaluation", {"purpose": "comparison"})\n'
 'input_ids = [left_artifacts[0]["id"], right_artifacts[0]["id"]]\n'
 'for artifact_id in input_ids:\n'
 '    manager.link_artifact(comparison.id, artifact_id, role="input")\n'
 'report, report_artifact = record_comparison(comparison, left, right,\n'
 '                                           work / "comparison.json", input_ids)\n',
 'training_id, artifact_id = training.id, checkpoint_artifact["id"]\n'
 'manager.close()\n'
 'manager = ExperimentManager(root)\n'
 'print(manager.list_runs(experiment_id=experiment["id"]))\n'
 'print(manager.get_run(training_id).read_metrics())\n'
 'print(manager.get_artifact(artifact_id))\n'
 'assert manager.verify_artifact(artifact_id)["status"] == "verified"\n'
 'manager.close()\n')
